import { posix } from "node:path";
import { MCP_CONTRACT, SKILL, isA, isAgentsFile } from "./artifacts.js";
import { frontmatter } from "./frontmatter.js";

export const SNAPSHOT = "data/instructions.snapshot";

const HEADER = [
  "# Instructions an agent loads",
  "",
  "Generated by `npm run snapshot`. CI fails when this file is stale, so regenerate it after changing an AGENTS.md, a skill or a tool contract.",
];

const byDepth = (a, b) => a.path.split("/").length - b.path.split("/").length || a.path.localeCompare(b.path);

function listing(files) {
  const lines = files.map(({ path, text }) => {
    const fields = frontmatter(text);
    const name = fields?.get("name")?.value || posix.basename(posix.dirname(path));
    return `- ${name}: ${fields?.get("description")?.value ?? ""} (${path})`;
  });
  return lines.length ? lines : ["- none"];
}

const section = (heading, lines) => [`## ${heading}`, "", ...lines, ""];

export function render({ files }) {
  const [agentsFiles, skills, contracts] = [isAgentsFile, isA(SKILL), isA(MCP_CONTRACT)].map((loads) => files.filter(loads).sort(byDepth));
  if (!agentsFiles.length && !skills.length && !contracts.length) return null;
  return [
    ...HEADER,
    "",
    ...agentsFiles.flatMap(({ path, text }) => section(path, [text.replace(/\r\n/g, "\n").trim()])),
    ...section("Skills", listing(skills)),
    ...section("Tools", listing(contracts)),
  ].join("\n").trimEnd() + "\n";
}

const fix = (state) => `snapshot is ${state}. Run \`npm run snapshot\` and commit the result.`;

export function check(repo) {
  const expected = render(repo);
  if (expected === null) return [];
  const actual = repo.files.find(({ path }) => path === SNAPSHOT)?.text.replace(/\r\n/g, "\n");
  if (actual === undefined) return [{ path: SNAPSHOT, line: 1, message: fix("missing") }];
  if (actual === expected) return [];
  const want = expected.split("\n");
  const have = actual.split("\n");
  const line = want.findIndex((text, i) => text !== have[i]) + 1 || have.length;
  return [{ path: SNAPSHOT, line, message: fix("stale from this line") }];
}
